import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Director:

    def __init__(self, builder, **kwargs):
        super(Director, self).__init__(**kwargs)
        self._builder = builder
        self._supported_log_types = {}
        for attr in dir(self.builder):
            if attr.startswith("add_") and not attr.startswith("add_prerequisite"):
                self._supported_log_types[
                    self._normalize_log_type(attr[4:])] = attr[4:]

    @staticmethod
    def _normalize_log_type(log_type):
        return log_type.replace(" ", "").replace("_", "").lower()

    @property
    def builder(self):
        return self._builder

    def get_normalize_matched_log_type(self, log_type):
        if self._normalize_log_type(log_type) in self._supported_log_types:
            return self._supported_log_types[self._normalize_log_type(log_type)]
        raise ValueError(
            f"Unknown type: {log_type!r}. Supported types are: {list(self._supported_log_types.values())}")

    def construct(self, ne_log_configurations):
        for ne_log_name, ne_log_configuration in ne_log_configurations.items():
            log_type = self.get_normalize_matched_log_type(ne_log_configuration['type'])
            getattr(self.builder, f"add_{log_type}")(
                ne_log_name=ne_log_name,
                ne_log_configuration=ne_log_configuration)
